def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    # Find rectangular outline components, paint their interiors with the associated marker
    # color (the distinct singleton color groups in these puzzles), in checkerboard form.
    from collections import Counter
    frames=[]
    for color in range(1,10):
        cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]==color}
        while cells:
            stack=[cells.pop()]; comp=set(stack)
            while stack:
                r,c=stack.pop()
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in cells: cells.remove(q); comp.add(q); stack.append(q)
            t=min(r for r,c in comp); b=max(r for r,c in comp); l=min(c for r,c in comp); rr=max(c for r,c in comp)
            if len(comp)>=8 and all(r in (t,b) or c in (l,rr) for r,c in comp):
                frames.append((color,t,b,l,rr))
    # Assign marker colors based on isolated source objects: non-frame colors form scattered markers.
    # In observed examples, the marker color groups have the fewest pixels versus background noise.
    for color,t,b,l,rr in frames:
        for r,c in ((r,c) for r in range(t,b+1) for c in range(l,rr+1) if r in (t,b) or c in (l,rr)):
            out[r][c]=color
    markers=[]
    frame_cells={(r,c) for _,t,b,l,rr in frames for r in range(t,b+1) for c in range(l,rr+1)}
    cnt=Counter(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] and (r,c) not in frame_cells)
    for c,n in cnt.items(): markers.append((n,c))
    markers.sort()
    # Use the colors of the two/three marker groups, ordered by visual association/frame position.
    # For the common three-frame layout, the smallest marker group tags the upper-left frame,
    # then larger groups tag lower-left and right frames.
    for i,(color,t,b,l,rr) in enumerate(sorted(frames,key=lambda f:(f[1],f[3]))):
        if not markers: break
        marker=markers[min(i,len(markers)-1)][1]
        for r in range(t+1,b):
            for c in range(l+1,rr):
                if (r-t-1+c-l-1)%2==0: out[r][c]=marker
    return out
